  app.innerHTML=`<div class="page-title"><div><span class="eyebrow">Customized Sprint</span><h1>Build a study sprint</h1><p>Choose a learning goal first, then add Fast Pace as an optional behavior.</p></div><button class="btn" id="sprintBack">← Home</button></div><div class="sprint-layout"><section class="panel setup-panel sprint-main"><h3>1. Choose the learning goal</h3><div class="choice-grid sprint-mode-grid">${modes.map(([v,t,d])=>`<button class="choice ${p.mode===v?'active':''}" data-sprint-mode="${v}"><strong>${t}</strong><small>${d}</small><span class="choice-total" data-mode-count="${v}">${formatCount(eligiblePool(v,p.section,p.topic,p.tag).length)} available</span></button>`).join('')}</div><h3 class="sprint-step">2. Choose pace, order, and size</h3><button class="toggle-card ${fast?'active':''}" id="sprintFastToggle" role="switch" aria-checked="${fast}"><span class="toggle-icon">⚡</span><span><strong>Fast Pace</strong><small>Instant correction plus automatic next question. Works with any learning goal.</small></span><span class="switch ${fast?'on':''}"><span></span></span></button><div class="field pace-delay ${fast?'':'is-hidden'}"><label>Auto-next delay (seconds)</label><input id="sprintDelay" type="number" class="input" min="0.5" max="15" step="0.5" value="${p.autoNextSeconds}"></div><div class="segmented"><button data-order="random" class="${p.order==='random'?'active':''}">Shuffle questions</button><button data-order="source" class="${p.order==='source'?'active':''}">Source order</button></div><div class="sprint-count-row"><div class="field"><label>Question count</label><input id="sprintCount" type="number" class="input" min="1" max="200" value="${p.count}"></div><div class="quick-counts">${[5,10,20,30,50].map(n=>`<button class="mini-btn ${p.count===n?'on':''}" data-count="${n}">${n}</button>`).join('')}</div></div></section><aside class="sprint-side"><section class="panel setup-panel"><h3>3. Focus filters</h3><div class="field"><label>Source section • ${formatCount(sections.length-1)}</label><select id="sprintSection">${selectOptionsCounted(sections,p.section,sectionCounts)}</select></div><div class="field"><label>Clinical topic • ${formatCount(topics.length-1)}</label><select id="sprintTopic">${selectOptionsCounted(topics,p.topic,topicCounts)}</select></div><div class="field"><label>Original collection tag • ${formatCount(tags.length-1)}</label><select id="sprintTag">${selectOptionsCounted(tags,p.tag,tagCounts)}</select></div><button class="mini-btn" id="resetSprintFilters">Reset filters</button></section><section class="panel sprint-summary"><span class="eyebrow">Live sprint preview</span><strong id="poolCount">0</strong><p id="poolText">matching questions</p><div id="sprintCounters"></div><div class="summary-lines" id="sprintSummary"></div><button class="btn primary" id="launchCustomSprint">Start customized sprint</button><div class="export-pair"><button class="mini-btn" id="exportSprintJson">{ } Export matching JSON</button><button class="mini-btn" id="exportSprintText">≡ Export refined text</button></div></section><section class="panel setup-panel"><h3>Quick presets</h3><div class="preset-grid"><button class="preset" data-preset="burst"><b>⚡ 10-Q Burst</b><small>Mixed bank + Fast Pace + 2-second auto-next</small></button><button class="preset" data-preset="mistakes"><b>↻ Mistake Rescue</b><small>20 incorrect questions; keeps your Fast Pace toggle</small></button><button class="preset" data-preset="new"><b>◌ New 20</b><small>20 unseen questions; keeps your Fast Pace toggle</small></button></div></section></aside></div>`;
  const readPrefs=()=>({...state.sprintPrefs,count:Math.max(1,Math.min(200,+document.getElementById('sprintCount').value||20)),section:document.getElementById('sprintSection').value,topic:document.getElementById('sprintTopic').value,tag:document.getElementById('sprintTag').value,autoNextSeconds:Math.max(.5,Math.min(15,parseFloat(document.getElementById('sprintDelay')?.value)||2))});
  const updatePreview=()=>{const prefs=readPrefs();state.sprintPrefs=prefs;save();modes.forEach(([mode])=>{const el=document.querySelector(`[data-mode-count="${mode}"]`);if(el)el.textContent=`${formatCount(eligiblePool(mode,prefs.section,prefs.topic,prefs.tag).length)} available`});const pool=customPool(prefs),available=pool.length,actual=Math.min(prefs.count,available),st=scopeStats(pool);document.getElementById('poolCount').textContent=formatCount(available);document.getElementById('poolText').textContent=available===1?'matching question':'matching questions';document.getElementById('sprintCounters').innerHTML=counterStrip([{label:'Will use',value:actual,tone:'accent'},{label:'Unseen',value:st.unseen},{label:'Correct',value:st.correct,tone:'good'},{label:'Review',value:st.wrong,tone:'warn'},{label:'Saved',value:st.bookmarks}],true);document.getElementById('sprintSummary').innerHTML=`<span><b>${formatCount(actual)}</b> will be used</span><span><b>${MODE_LABELS[prefs.mode]||'Study Sprint'}</b> goal</span><span><b>${prefs.fastPace?'Fast Pace ON':'Standard pace'}</b></span><span><b>${prefs.order==='random'?'Shuffled':'Source order'}</b></span>${prefs.fastPace?`<span><b>${prefs.autoNextSeconds}s</b> auto-next</span>`:''}`;const launch=document.getElementById('launchCustomSprint');launch.disabled=!available;launch.textContent=available?`Start ${actual}-question sprint`:'No matching questions';document.getElementById('exportSprintJson').disabled=!available;document.getElementById('exportSprintText').disabled=!available};
  document.getElementById('sprintBack').onclick=()=>setRoute('home');
  document.querySelectorAll('[data-sprint-mode]').forEach(b=>b.onclick=()=>{state.sprintPrefs.mode=b.dataset.sprintMode;save();renderSprintBuilder()});
